children = [
    {"id": "child_1", "text": "The refund window is thirty days.", "parent_id": "parent_A"},
    {"id": "child_2", "text": "Refunds require a receipt.", "parent_id": "parent_A"},
    {"id": "child_3", "text": "Shipping takes five to seven days.", "parent_id": "parent_B"},
]

parents = {
    "parent_A": "Full refund policy: The refund window is thirty days. Refunds require a receipt. Contact support to begin the process.",
    "parent_B": "Full shipping policy: Shipping takes five to seven days. International orders may take longer.",
}

def search_children(query_terms, children):
    return [c for c in children if any(term.lower() in c["text"].lower() for term in query_terms)]

def retrieve_deduped_parents(matched_children, parents):
    # Deduplicate parents shared by multiple matched children
    seen_parent_ids = set()
    results = []
    for child in matched_children:
        parent_id = child["parent_id"]
        if parent_id not in seen_parent_ids:
            seen_parent_ids.add(parent_id)
            results.append(parents[parent_id])
    return results

matched = search_children(["refund"], children)
print(f"Matched children:")
for c in matched:
    print(f"  {c}")

final_context = retrieve_deduped_parents(matched, parents)
print(f"\nFinal deduplicated parent context:")
for p in final_context:
    print(f"  {p!r}")
